import assert from "node:assert/strict";
import { test } from "node:test";
import { GATEWAY_TIMEOUT_MS } from "../src/config.ts";
import { placeOrder } from "../src/orders/checkout.ts";
import type { Gateway } from "../src/payments/gateway.ts";

// INC-2026-001: UPI and card confirmations take 2 to 8 seconds. Customers were
// charged while their orders were marked failed.
const slowGateway = (delayMs: number): Gateway => ({
  authorize: (request) => new Promise((resolve) => setTimeout(() => resolve({ status: "captured", paymentId: `pay_${request.orderId}` }), delayMs)),
});
const silentGateway: Gateway = { authorize: () => new Promise(() => {}) };

test("a UPI payment confirmed after 4 seconds completes the order", async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  const order = placeOrder(slowGateway(4_000), { orderId: "o3", amountInr: 2499, method: "upi" });
  t.mock.timers.tick(4_000);
  assert.equal((await order).status, "PAID");
});

test("a gateway timeout leaves the order pending, never failed", async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  const order = placeOrder(silentGateway, { orderId: "o4", amountInr: 1299, method: "upi" });
  t.mock.timers.tick(GATEWAY_TIMEOUT_MS);
  assert.equal((await order).status, "PENDING");
});

